package main
import("fmt";"io";"net/http";"os";"strings";"time";"github.com/golang-jwt/jwt/v5";"gorm.io/driver/sqlite";"gorm.io/gorm";"webbuilder/internal/database/models")
func main(){db,e:=gorm.Open(sqlite.Open("../../../data/webbuilder.db"),&gorm.Config{});if e!=nil{panic(e)};var u models.User;db.First(&u);var p models.Project;db.Where("user_id = ?",u.ID).Order("id DESC").First(&p);sec,_:=os.ReadFile("../../../.jwt-secret");t:=jwt.NewWithClaims(jwt.SigningMethodHS256,jwt.MapClaims{"uid":u.ID,"exp":time.Now().Add(time.Hour).Unix()});tok,_:=t.SignedString([]byte(strings.TrimSpace(string(sec))));for _,x:=range []struct{m,path string}{{"GET",fmt.Sprintf("/api/projects/%d/runtime/info",p.ID)},{"POST",fmt.Sprintf("/api/projects/%d/runtime/install",p.ID)},{"POST",fmt.Sprintf("/api/projects/%d/runtime/build",p.ID)},{"POST",fmt.Sprintf("/api/projects/%d/runtime/db-verify",p.ID)}}{req,_:=http.NewRequest(x.m,"http://127.0.0.1:18082"+x.path,nil);req.Header.Set("Authorization","Bearer "+tok);resp,e:=http.DefaultClient.Do(req);if e!=nil{fmt.Println(x.path,"ERR",e);continue};b,_:=io.ReadAll(resp.Body);resp.Body.Close();fmt.Printf("%s %d %s\n",x.path,resp.StatusCode,string(b));}}